int cmp(const void *a, const void *b){
    int x = *(const int *)a, y = *(const int *)b;
    int tx = tong(x), ty = tong(y);
    if(tx != ty) return (tx > ty) - (tx < ty);  // tong tang
    return (x < y) - (x > y);                   // so lon truoc
}
