typedef struct { char ten[30]; double gpa; } SinhVien;

int cmp(const void *a, const void *b){
    const SinhVien *s1 = (const SinhVien *)a;
    const SinhVien *s2 = (const SinhVien *)b;
    if(s1->gpa != s2->gpa)
        return (s1->gpa < s2->gpa) - (s1->gpa > s2->gpa); // gpa giam
    return strcmp(s1->ten, s2->ten);                      // ten A-Z
}

int cmp2Chieu(const void *a, const void *b){
    return strcmp((const char *)a, (const char *)b);
}
int cmpConTro(const void *a, const void *b){
    return strcmp(*(const char * const *)a,
                  *(const char * const *)b);
}
